+    // Diagnostic-only instrumentation. This worktree is never a shipping build.
+    // Snapshots run outside the timed interval. No collection is requested.
+    private static JsonObject ParentMemoryDiagnosticSnapshot(Process process)
+    {
+        long totalMemory = GC.GetTotalMemory(forceFullCollection: false);
+        GCMemoryInfo info = GC.GetGCMemoryInfo();
+        long allocated = GC.GetTotalAllocatedBytes(precise: true);
+        int gen0 = GC.CollectionCount(0), gen1 = GC.CollectionCount(1), gen2 = GC.CollectionCount(2);
+        process.Refresh();
+        long workingSet = process.WorkingSet64;
+        long peakWorkingSet = process.PeakWorkingSet64;
+        var generations = new JsonArray();
+        int generation = 0;
+        foreach (GCGenerationInfo value in info.GenerationInfo)
+        {
+            generations.Add(new JsonObject
+            {
+                ["generation"] = generation++, ["sizeBeforeBytes"] = value.SizeBeforeBytes,
+                ["fragmentationBeforeBytes"] = value.FragmentationBeforeBytes,
+                ["sizeAfterBytes"] = value.SizeAfterBytes,
+                ["fragmentationAfterBytes"] = value.FragmentationAfterBytes,
+            });
+        }
+        return new JsonObject
+        {
+            ["workingSetBytes"] = workingSet, ["peakWorkingSetBytes"] = peakWorkingSet,
+            ["gcGetTotalMemoryBytes"] = totalMemory, ["totalAllocatedBytes"] = allocated,
+            ["gcCollectionCounts"] = new JsonArray(gen0, gen1, gen2),
+            ["heapSizeBytes"] = info.HeapSizeBytes, ["fragmentedBytes"] = info.FragmentedBytes,
+            ["totalCommittedBytes"] = info.TotalCommittedBytes, ["memoryLoadBytes"] = info.MemoryLoadBytes,
+            ["gcIndex"] = info.Index, ["gcGeneration"] = info.Generation,
+            ["gcCompacted"] = info.Compacted, ["gcConcurrent"] = info.Concurrent,
+            ["generationInfo"] = generations,
+        };
+    }
+
